 "content": "def transform(grid):
    """Replicate the irregular tile pattern, recolored by each tile-row key."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Separators are the full-width/full-height grid lines.
    sep = max(set(v for row in g for v in row), key=lambda v: sum(row.count(v) for row in g))
    hlines = [r for r, row in enumerate(g) if all(v == sep for v in row)]
    vlines = [c for c in range(w) if all(g[r][c] == sep for r in range(h))]
    if not hlines or hlines[0] != 4 or not vlines or vlines[0] != 4:
        raise ValueError("expected regularly separated 4x4 tiles")
    rh = [0] + [r + 1 for r in hlines]
    rh_end = hlines + [h]
    cw = [0] + [c + 1 for c in vlines]
    cw_end = vlines + [w]
    tile_h = rh_end[0] - rh[0]
    tile_w = cw_end[0] - cw[0]

    tiles = []
    for r0, r1 in zip(rh, rh_end):
        row = []
        for c0, c1 in zip(cw, cw_end):
            row.append([[g[r][c] for c in range(c0, c1)] for r in range(r0, r1)])
        tiles.append(row)

    # The first column gives the color key for each tile row; its 2x2
    # colored square is not the pattern to replicate.
    keys = []
    for tile_row in tiles:
        colors = {v for row in tile_row[0] for v in row if v != 0 and v != sep}
        if len(colors) != 1:
            raise ValueError("could not identify a single color key in first tile")
        keys.append(next(iter(colors)))

    # Find the lone non-square motif elsewhere in the lattice.
    candidates = []
    for tr, tile_row in enumerate(tiles):
        for tc, tile in enumerate(tile_row):
            cells = [(r, c, tile[r][c]) for r in range(tile_h) for c in range(tile_w)
                     if tile[r][c] not in (0, sep)]
            if not cells:
                continue
            # Ignore the 2x2 color-key objects.
            if len(cells) == 4 and len({x[0] for x in cells}) == 2 and len({x[1] for x in cells}) == 2:
                continue
            candidates.append([(r, c) for r, c, _ in cells])
    if len(candidates) != 1:
        raise ValueError("expected exactly one irregular motif")
    motif = candidates[0]

    out = [[0 for _ in range(w)] for _ in range(h)]
    for r in hlines:
        out[r] = [sep] * w
    for c in vlines:
        for r in range(h):
            out[r][c] = sep
    for tr, (r0, r1) in enumerate(zip(rh, rh_end)):
        for c0, c1 in zip(cw, cw_end):
            for dr, dc in motif:
                out[r0 + dr][c0 + dc] = keys[tr]
    return out


